"""The Docker implementation of :class:`~workpeg.sandbox.driver.SandboxDriver`.

Docker shares the host kernel, so a container is a resource-control
mechanism and not a security boundary. Everything here is written on that
assumption: the flags below reduce what an escape is worth, they do not
prevent one, and the endpoint of this work is a microVM. What this driver is
responsible for is that the reduction is *unconditional* — there is no path
through it that produces a container missing a control.

**The daemon is remote, and must be.** ``endpoint`` is required and must be
``tcp://``. The alternative — a Unix socket — means the host's docker socket
is mounted into the process holding this driver, and socket access is full
daemon control: it turns an install-time risk into a request-time one. So a
socket path is refused outright rather than merely discouraged, which makes
"the API never holds the host socket" a property of this file instead of a
property of a compose file somebody may edit. The corollary is that the
network between this process and that daemon carries unauthenticated root —
it has to be a private one, and that is deployment's job, not this file's.

**The flag list, and why each one is there.**

``--network``
    ``none``, or a per-owner ``--internal`` bridge. Never the platform
    bridge, which cannot be named from here at all.
``--restart no``
    Explicit, because the install path's ``--restart unless-stopped`` is
    precisely how containers leak forever: a restarting container survives
    the reaper's ``stop`` and outlives the row that remembered it.
``--cap-drop ALL`` / ``--security-opt no-new-privileges``
    Nothing is added back, and a setuid binary inside cannot climb.
``--read-only`` + a ``noexec`` tmpfs
    The image is the only thing that can be executed; a payload written at
    runtime has nowhere to land that it can run from.
``--user``
    ``nobody``. Root in a container is root in the kernel's eyes for every
    bug that matters.
``--pids-limit`` / ``--memory`` / ``--memory-swap`` / ``--cpus``
    ``--memory-swap`` is set equal to ``--memory`` deliberately: leaving it
    unset lets the container swap to twice its memory limit, which makes the
    memory limit approximately advisory.

**Nothing follows the image on ``create``.** The argv ends at the image
reference — no command, no arguments. What a container starts as is what its
Dockerfile declares. Commands arrive later, through ``exec``, one at a time
and each with its own deadline, which is a different thing from an
entrypoint somebody can rewrite.

**Nothing precedes it either.** No ``-e``, no ``--env-file``, no ``-v``, no
``--mount``. A secret that is never passed cannot be dumped out of
``/proc/self/environ`` — and ``exec`` adds none of them back, which is a
thing its own tests assert rather than a thing this file merely intends.

**``docker exec`` is how a command runs, and the reason is the sidecar.**
Sandboxes live in the DinD daemon's network namespace, so no address the API
can form reaches one; 4.3 measured that twice. ``exec`` is a call to the
*daemon*, over the TLS connection the platform already has, so the container
never needs to be addressable at all — which is also why a sandbox can go
back to having no network.

**Every exec is unprivileged and cannot become privileged.** ``--user`` is
passed explicitly rather than inherited, ``--privileged`` is never passed,
and the container's own ``no-new-privileges`` applies to the process ``exec``
starts. The last of those is the kernel's doing rather than this file's, so
it is checked against a real container rather than asserted here.
"""
import subprocess
import threading
import time
from typing import Callable

from workpeg.sandbox.driver import (
    DEFAULT_EXEC_TIMEOUT, DEFAULT_TTL, LABEL, MAX_OUTPUT_BYTES, SANDBOX_USER,
    SLOW_CONSUMER_SHARE, TMPFS_SPEC, ExecResult, Handle, Limits, Network,
    OutputRelay, SandboxConfigError, SandboxError, SandboxExists,
    SandboxNotRunning, SandboxTimeout, State, Status, bump, container_name,
    network_name, scrub_output, validate_argv, validate_exec_timeout,
    validate_image, validate_network, validate_owner, validate_stdin,
    validate_ttl,
)

#: Bounds every docker command. A daemon that has stopped answering must not
#: become a request that never returns.
DOCKER_TIMEOUT = 30.0

#: How much is taken from the output pipe at a time. Small enough that the
#: cap is enforced promptly, large enough not to syscall per line.
READ_CHUNK = 64 * 1024

#: The question "is there a daemon there at all?", and the cheapest one that
#: cannot be answered without one.
#:
#: ``version`` is the probe because the answer comes from the SERVER. The
#: client's own version is printed with no daemon anywhere — that is the
#: whole reason a bare ``docker version`` is not a liveness check — so the
#: format string asks for ``.Server.Version`` specifically, and an empty
#: answer counts as no answer. Nothing reads the text itself; what is used
#: is the exit status and whether a server field came back.
VERSION_PROBE = ["version", "--format", "{{.Server.Version}}"]

#: Docker's own state strings, mapped onto ours.
#:
#: An unrecognised state maps to ``STOPPED``, never ``GONE``, and that
#: direction is deliberate: the daemon answered, so the container exists, and
#: ``GONE`` is the one answer that tells a reaper to stop trying to remove
#: it. A new Docker state must not become a leak.
_STATES = {
    "running": State.RUNNING,
    "restarting": State.RUNNING,
    "created": State.STOPPED,
    "paused": State.STOPPED,
    "removing": State.STOPPED,
    "exited": State.STOPPED,
    "dead": State.STOPPED,
}


def run_argv(*, name, owner, image, limits, network) -> list:
    """The full ``docker run`` argv for one sandbox.

    A module-level function rather than a method so the hardening can be
    asserted without a daemon, a socket, or a mock of either: the thing the
    tests need to check is exactly this list.
    """
    attach = "none" if network is Network.NONE else network_name(owner)
    return [
        "run", "--detach",
        "--name", name,
        "--network", attach,
        # Never unless-stopped: a restarting container outlives the reaper.
        "--restart", "no",
        "--cap-drop", "ALL",
        "--security-opt", "no-new-privileges:true",
        "--read-only",
        "--tmpfs", TMPFS_SPEC,
        "--user", SANDBOX_USER,
        "--pids-limit", str(limits.pids),
        "--memory", f"{limits.memory_mb}m",
        # Equal to --memory, so the limit is a limit and not a doubling.
        "--memory-swap", f"{limits.memory_mb}m",
        "--cpus", str(limits.cpus),
        "--label", f"{LABEL}=1",
        "--label", f"{LABEL}.owner={owner}",
        # The image is last and nothing follows it: no command, no args.
        image,
    ]


def exec_argv(*, name, argv, stdin=False) -> list:
    """The full ``docker exec`` argv for one command.

    Module-level for the same reason as :func:`run_argv`: what has to be
    checked is this list, and checking it must not need a daemon.

    Three properties, in the order they matter.

    ``--user``
        Passed explicitly, not inherited. ``docker exec`` does default to
        the user the container was created with, so this is belt and braces
        — but the belt is a default in somebody else's program and the
        braces cost nine characters.
    ``--``
        Ends flag parsing before the container name. Docker already stops
        reading its own flags at that point (measured: ``docker exec c echo
        --privileged`` prints ``--privileged``), so this guards a future
        version rather than today's.
    ``--interactive``, only with stdin
        Without it the daemon does not attach stdin at all, so a command
        given nothing to read sees end-of-file immediately instead of a
        pipe somebody might later fill.

    What is absent is the list worth reading: no ``--privileged``, no
    ``--tty`` (which would let a command emit terminal escapes into a
    transcript and would rewrite its own newlines), no ``--detach`` (which
    would throw away the exit code and the output), and no ``--env``.
    """
    return [
        "exec",
        # Never inherited, never a caller's choice, never root.
        "--user", SANDBOX_USER,
        *(["--interactive"] if stdin else []),
        # Nothing after this can be read as a flag of docker's own.
        "--",
        name,
        *argv,
    ]


def network_argv(name: str) -> list:
    """The argv creating an owner's isolated bridge.

    ``--internal`` is the whole of it. Without that flag Docker attaches a
    gateway and the "isolated" network reaches the internet.
    """
    return ["network", "create", "--internal", "--driver", "bridge", name]


def validate_endpoint(endpoint) -> str:
    """The daemon this driver talks to.

    ``tcp://`` only. A Unix socket here means the host's docker socket is
    mounted into this process, and that is full daemon control — the one
    thing the sidecar exists to avoid.
    """
    if not isinstance(endpoint, str) or not endpoint.startswith("tcp://"):
        raise SandboxConfigError(
            f"endpoint {endpoint!r} must be a tcp:// address for a remote "
            f"docker daemon. A unix socket is refused: mounting the host's "
            f"docker socket into this process is full daemon control, which "
            f"is the risk the separate daemon exists to remove.")
    if len(endpoint) <= len("tcp://"):
        raise SandboxConfigError("endpoint names no host")
    return endpoint


def subprocess_runner(*, env=None):
    """The process boundary, with an environment optionally bound to it.

    A factory rather than a function because the one thing a deployment
    legitimately needs to vary is the environment — the docker client reads
    its TLS material from ``DOCKER_CERT_PATH``, and that must be bound to
    *these* subprocesses rather than set on the calling process, where it
    would break every other docker client in the same container.

    It is exported so that a caller needing that never has to write a
    ``subprocess.run`` of its own. That is not convenience: the bounded read
    below is a security property, and a caller that reimplemented this seam
    to add an environment would silently drop it.

    Two shapes, chosen by ``limit``:

    * no limit — a control command (``ps``, ``inspect``, ``run``). Output is
      docker's own, small and textual, and stderr is wanted separately
      because a failure message is the useful part.
    * a limit — a command inside a sandbox. Output is untrusted and
      unbounded, so it is read through a cap and the process is killed when
      it passes it.

    ``on_chunk`` belongs to the second shape and only to it. It is handed
    each read as BYTES, in read order, on this thread — the decode is the
    seam's policy and lives in
    :class:`~workpeg.sandbox.driver.OutputRelay`, where a backend cannot
    quietly drop it. Passing one with no limit is refused rather than
    ignored: a control command's output is docker's own and is read in one
    go, so a caller expecting it a piece at a time has misunderstood which
    of the two shapes it asked for, and silence would let it keep doing so.
    """
    def run(argv, timeout, *, stdin=None, limit=None, on_chunk=None):
        if limit is None:
            if on_chunk is not None:
                raise SandboxConfigError(
                    "a command read without a limit does not stream: its "
                    "output is the daemon's own and is read in one go. "
                    "on_chunk is for a command running inside a sandbox.")
            return subprocess.run(argv, capture_output=True, text=True,
                                  timeout=timeout, env=env)
        return _run_bounded(argv, timeout, stdin=stdin, limit=limit, env=env,
                            on_chunk=on_chunk)
    return run


def _run_bounded(argv, timeout, *, stdin, limit, env, on_chunk=None):
    """Run ``argv``, reading at most ``limit`` bytes, then killing it.

    The cap is on the READ. ``subprocess.run`` would buffer everything a
    command printed before anyone could trim it, so a sandbox that printed a
    gigabyte would cost the platform a gigabyte of memory — the exact
    failure 4.1's streamed HTTP read existed to prevent, and the one thing a
    naive port of this transport would have thrown away.

    Standard error is merged into standard output rather than given a second
    pipe. Two pipes read from one thread deadlock the moment either fills,
    and the alternative — a reader thread apiece — buys a distinction
    nothing downstream uses: :class:`~workpeg.sandbox.driver.ExecResult` has
    one ``output`` field because what a person reads is what the command
    printed, in the order it printed it.

    The deadline is a watchdog rather than a deadline on each read, because
    a read from a silent process blocks indefinitely and would sail past
    any check made between reads.

    ``read1`` is what makes this incremental: it returns as soon as anything
    is available rather than waiting for a full buffer, so the loop already
    saw a command's output arrive in pieces long before anything asked for
    them. ``on_chunk`` is handed each of those pieces where it is read —
    on this thread, between two reads — and the cap, the kill and the
    watchdog are untouched by it.

    It is handed nothing once the watchdog has fired. The deadline has to
    bound the hand-over and not only the command, because the hand-over is
    the part that runs on this thread: killing the process does not
    interrupt a consumer, it just leaves a full pipe for the loop to drain
    into one.
    """
    process = subprocess.Popen(
        argv,
        # DEVNULL, not a pipe, when there is nothing to send: a command that
        # reads stdin then gets EOF, rather than one that waits on a pipe
        # nobody will ever write to.
        stdin=subprocess.PIPE if stdin is not None else subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=env)

    expired = []

    def expire():
        expired.append(True)
        process.kill()

    watchdog = threading.Timer(timeout, expire)
    watchdog.start()
    try:
        if stdin is not None:
            # One write, guaranteed to fit the pipe buffer, then closed —
            # see MAX_STDIN_BYTES. A broken pipe here is a command that
            # exited without reading, which is its business, not an error.
            try:
                process.stdin.write(stdin)
            except OSError:
                pass
            finally:
                try:
                    process.stdin.close()
                except OSError:
                    pass

        chunks, size = [], 0
        try:
            while size <= limit:
                block = process.stdout.read1(READ_CHUNK)
                if not block:
                    break
                chunks.append(block)
                size += len(block)
                if on_chunk is not None and not expired:
                    # Handed over HERE: on this thread, between two reads,
                    # before the next read1 blocks. Never from the watchdog,
                    # which does one thing and has to keep doing one thing.
                    #
                    # `expired` is the deadline, read where it can still stop
                    # something. Past it the watchdog has killed the command
                    # and this call is going to raise, so these last reads
                    # reach nobody through the result — handing them on
                    # would show a person text the model was never shown,
                    # and would spend the caller's thread on a display for
                    # an answer that is being thrown away. Without this the
                    # deadline stops bounding `exec` at all: the loop drains
                    # the pipe the kill left behind and calls a slow
                    # consumer again, measured at twice its per-call stall
                    # for as many reads as the buffer holds.
                    on_chunk(block)
        except BaseException:
            # Nobody will read this pipe again, so nothing may be left
            # attached to a command still writing into it. The watchdog is
            # cancelled in the `finally` below, so an exception escaping
            # this loop would orphan the process with nothing left to kill
            # it. That was latent while only `read1` could raise; it is a
            # live path now that a caller's code runs in here.
            process.kill()
            process.stdout.close()
            process.wait()
            raise
        if size > limit:
            # It has said more than anyone will read. Stopping it here is
            # what stops a command that prints forever from holding a worker
            # until its deadline.
            process.kill()
        process.stdout.close()
        returncode = process.wait()
    finally:
        watchdog.cancel()
        # Joined, not just cancelled: a timer that fired between the last
        # read and the cancel has already killed the process, and treating
        # that as a clean exit would report a timeout as a command that
        # died for no stated reason.
        watchdog.join()

    if expired:
        raise subprocess.TimeoutExpired(argv, timeout)
    return subprocess.CompletedProcess(argv, returncode, b"".join(chunks), b"")


class DockerDriver:
    """Drives sandboxes on a remote Docker daemon.

    ``runner`` is the one process boundary, injectable so the whole of this
    class is testable with no Docker present — which is the difference
    between hardening that is checked on every run of the suite and
    hardening that is checked when somebody remembers to install Docker.
    There is no longer an ``http`` seam beside it, because nothing here
    speaks HTTP: the daemon connection is the only connection.
    """

    def __init__(self, *, endpoint, runner=None, clock=time.time):
        self.endpoint = validate_endpoint(endpoint)
        self._runner = runner or subprocess_runner()
        self._clock = clock

    # -- the daemon --------------------------------------------------

    def _docker(self, args, *, timeout=DOCKER_TIMEOUT, stdin=None,
                limit=None, on_chunk=None):
        argv = ["docker", "--host", self.endpoint, *args]
        # Passed only when there is one, so a runner written against this
        # seam as it was keeps running every command that does not stream —
        # which is all of them until a caller opts in. `runner` is a public
        # constructor argument and there are custom ones outside this repo.
        extra = {} if on_chunk is None else {"on_chunk": on_chunk}
        try:
            return self._runner(argv, timeout, stdin=stdin, limit=limit,
                                **extra)
        except FileNotFoundError as exc:
            raise SandboxError(
                "Docker not found. The 'docker' client must be on PATH for "
                "the sandbox driver to reach its daemon.") from exc
        except subprocess.TimeoutExpired as exc:
            raise SandboxTimeout(
                f"docker {args[0]} timed out after {timeout}s") from exc

    def _checked(self, args, *, what, timeout=DOCKER_TIMEOUT):
        result = self._docker(args, timeout=timeout)
        if result.returncode != 0:
            raise SandboxError(
                f"{what} failed (exit {result.returncode}): "
                f"{(result.stderr or '').strip()[:400]}")
        return result

    def _require_daemon(self, what) -> None:
        """Raise unless the daemon is there to have answered.

        **A failed docker command says nothing about why, on its own.**
        ``docker inspect`` exits non-zero when the daemon answered and has
        no such container, and it exits non-zero when there was no daemon to
        ask. Those are opposite facts arriving as one exit status, and the
        first of them is :attr:`~workpeg.sandbox.driver.State.GONE` — the
        one answer that tells every caller to stop trying. A caller acts on
        it by throwing away the row that is its only handle on a container,
        so it must not be reached by inference from an exit code.

        **The error text is not read, and that is the same rule as
        ``exec``'s.** Separating the two cases by grepping stderr for "No
        such container" would put the decision in a string, and a sandbox
        can print any string it likes — including docker's own. So the
        question is put to the daemon, which is the only party in this that
        cannot be lied to.

        The direction of the doubt is deliberate. A probe that is wrong here
        says "unreachable", which costs a retry; the other way round costs
        somebody a running container nothing can name again.
        """
        probe = self._docker(VERSION_PROBE)
        if probe.returncode != 0 or not (probe.stdout or "").strip():
            raise SandboxError(
                f"the docker daemon at {self.endpoint} did not answer, so "
                f"{what} is unknown. Nothing may be concluded about the "
                f"sandbox from this: a daemon that cannot be reached looks "
                f"exactly like a container that is gone, and they are "
                f"opposite facts.")

    # -- lifecycle ---------------------------------------------------

    def create(self, *, owner: str, image: str,
               limits: "Limits | None" = None,
               network: Network = Network.NONE,
               ttl: float = DEFAULT_TTL) -> Handle:
        """Start a hardened sandbox for ``owner``.

        Every safety property is applied here and none of them appear in
        this signature. What a caller chooses is who it is for, what runs,
        how big it may be within a validated range, and how long it lives.
        """
        owner = validate_owner(owner)
        image = validate_image(image)
        network = validate_network(network)
        ttl = validate_ttl(ttl)
        if limits is None:
            limits = Limits()
        elif not isinstance(limits, Limits):
            raise SandboxConfigError(
                "limits must be a Limits instance — it is validated on "
                "construction, and a bare dict would skip that")

        name = container_name(owner)
        if self._exists(name):
            # One sandbox per staff member, reused across their chats. The
            # answer to a second create is the first one, by name.
            raise SandboxExists(name)

        if network is Network.ISOLATED:
            self._ensure_network(network_name(owner))

        result = self._checked(
            run_argv(name=name, owner=owner, image=image, limits=limits,
                     network=network),
            what=f"creating sandbox {name}")

        created = self._clock()
        return Handle(
            owner=owner,
            name=name,
            container_id=(result.stdout or "").strip(),
            image=image,
            network=network,
            limits=limits,
            created_at=created,
            expires_at=created + ttl,
        )

    def status(self, handle: Handle) -> Status:
        """What the daemon says about this sandbox now.

        **A failed ``inspect`` is not by itself an answer**, and this method
        used to treat it as one. It exits non-zero both when the daemon
        answered and does not know the container — genuinely ``GONE`` — and
        when there was no daemon to ask, which is a question that has not
        been answered at all. The two were conflated, and the damage was not
        theoretical: a caller reconciles ``GONE`` by deleting the row that
        remembers the container, so the first minute a daemon spent
        restarting deleted the only handle anybody had on containers that
        were still running.

        So a non-zero exit asks :meth:`_require_daemon` whether there is a
        daemon there, and ``GONE`` is returned only once something has
        answered. If nothing has, this raises
        :class:`~workpeg.sandbox.driver.SandboxError` or
        :class:`~workpeg.sandbox.driver.SandboxTimeout` — "I do not know",
        which a caller can retry, rather than "it is gone", which a caller
        acts on once and cannot undo.

        The cost is one extra command, on the path that had already failed.
        """
        _require_handle(handle)
        result = self._docker(
            ["inspect", "--format", "{{.State.Status}} {{.State.ExitCode}}",
             handle.name])
        if result.returncode != 0:
            # Raises if nothing answered. Reached only when there IS a
            # daemon and it does not have this container.
            self._require_daemon(f"the state of {handle.name}")
            return Status(state=State.GONE,
                          container_id=handle.container_id)

        parts = (result.stdout or "").split()
        raw = parts[0] if parts else ""
        try:
            exit_code = int(parts[1])
        except (IndexError, ValueError):
            exit_code = None
        return Status(state=_STATES.get(raw, State.STOPPED),
                      container_id=handle.container_id,
                      exit_code=exit_code)

    def keepalive(self, handle: Handle, ttl: float) -> Handle:
        """Push the deadline out, returning the handle to persist.

        Touches no container: there is nowhere on one to write a deadline
        (labels are fixed at create), so the new expiry travels back to the
        caller, who owns it.
        """
        _require_handle(handle)
        return bump(handle, ttl, self._clock())

    def destroy(self, handle: Handle) -> None:
        """Remove the container, then anything created alongside it.

        Both steps ignore failure, and that is what makes this idempotent:
        the reaper and a person clicking a button race by design, and the
        loser must not raise. The order is fixed — a network with a
        container still attached cannot be removed, so removing it first
        would leak it every time.
        """
        _require_handle(handle)
        self._docker(["rm", "--force", "--volumes", handle.name])
        if handle.network is Network.ISOLATED:
            self._docker(["network", "rm", network_name(handle.owner)])

    # -- work --------------------------------------------------------

    def exec(self, handle: Handle, argv: list, *,
             timeout: float = DEFAULT_EXEC_TIMEOUT,
             stdin: "bytes | str | None" = None,
             on_output: "Callable[[str], None] | None" = None) -> ExecResult:
        """Run ``argv`` in the sandbox, as its unprivileged user.

        Everything is validated before the daemon is touched, in that order
        deliberately: a refused command must not be one that started and was
        then stopped.

        **A non-zero exit asks the daemon what state the container is in.**
        ``docker exec`` reports "the container is not running" the same way
        it reports "your command exited 1" — exit status 1, with the
        difference only in a message. Reading that message would mean a
        sandbox could print it and talk the platform into believing itself
        dead, so the question is put to the daemon instead, which is the only
        party that cannot be lied to. It costs one ``inspect`` — and, when
        that fails too, one version probe — on the paths that already
        failed.

        **A daemon that went away mid-command is not a dead sandbox.**
        :meth:`status` raises rather than answering ``GONE`` when nothing
        replied, and that exception travels out of here as itself. It is
        deliberately not converted into
        :class:`~workpeg.sandbox.driver.SandboxNotRunning`, because callers
        treat that one as settled — they record the sandbox as stopped and
        refuse it from then on. A blip must not be able to brick a container
        that is still running.

        **A timeout kills the client, not the command.** The process inside
        the container keeps running: nothing here can name it to signal it.
        That is contained rather than solved — the pids, memory and CPU
        limits bound what it can do and the reaper destroys the container —
        and it is written down because a reader who assumed otherwise would
        be wrong in a way nothing visible would correct.

        **``on_output`` is the pipe this method already had, handed out.**
        The bounded read below has always taken the command's output a piece
        at a time; joining the pieces at the end was only ever because
        nobody had asked for them earlier. Nothing about the cap, the kill
        or the stdin ordering moves to make room for it, and everything the
        consumer is handed still joins up to ``result.output``. The full
        contract — same thread, text in, return value ignored, a consumer
        that raises does not fail the command — is on
        :meth:`~workpeg.sandbox.driver.SandboxDriver.exec` and is the seam's
        rather than this backend's.

        The deadline is the one thing that does move, and it moves to keep
        meaning what it meant. It now bounds the hand-over as well as the
        command, in the two places the seam requires: the read loop stops
        handing over once the watchdog has fired, and the relay stops once
        the consumer has spent its share. Left alone, ``timeout`` would have
        bounded only the process — a consumer is not something ``kill``
        reaches — and this method would hold a worker thread for as long as
        somebody else's callback felt like holding it.

        **A command whose output is block-buffered still streams nothing,
        and that is not this hook.** A program writing to a pipe buffers by
        default, so ``python foo.py`` inside a sandbox says nothing until it
        flushes or exits however this is called. ``--tty`` would change that
        and is refused for a better reason (terminal escapes into a
        transcript, and rewritten newlines — see :func:`exec_argv`), so the
        answer belongs to the caller: ``python -u``, or ``stdbuf -oL``.
        """
        _require_handle(handle)
        argv = validate_argv(argv)
        timeout = validate_exec_timeout(timeout)
        stdin = validate_stdin(stdin)
        # Constructing the relay IS the validation of ``on_output``, and it
        # belongs with the other three: a command refused for its consumer
        # must not be one that started, printed, and was then stopped.
        relay = None if on_output is None else OutputRelay(
            on_output, MAX_OUTPUT_BYTES, deadline=timeout)

        started = self._clock()
        try:
            result = self._docker(
                exec_argv(name=handle.name, argv=argv,
                          stdin=stdin is not None),
                timeout=timeout, stdin=stdin, limit=MAX_OUTPUT_BYTES,
                on_chunk=None if relay is None else relay.feed)
        except SandboxTimeout as exc:
            # A consumer runs on the command's clock, so a slow one can time
            # out a command that would have finished — and this exception
            # names the sandbox, which would send somebody to read the wrong
            # program. Said only when the relay had already cut the consumer
            # off, which is the same condition: blaming it for every timeout
            # is how a true sentence stops being read.
            #
            # `overran` rather than the arithmetic, so the sentence and the
            # cut-off cannot drift apart, and so this does not have to say
            # how `elapsed` compares to `timeout` — it can exceed it, by
            # whatever the call in flight at the deadline cost.
            if relay is not None and relay.overran:
                raise SandboxTimeout(
                    f"{exc}. on_output held the thread for "
                    f"{relay.elapsed:.1f}s before it was cut off for going "
                    f"past its {SLOW_CONSUMER_SHARE:.0%} share of that "
                    f"deadline, so this may be a slow consumer rather than a "
                    f"slow command. A consumer runs inside the read loop, on "
                    f"the thread that called exec, and must hand the text on "
                    f"and do nothing else.") from exc
            raise
        finally:
            # In a `finally` on purpose. A command that hit its deadline has
            # already printed whatever it printed, and somebody has already
            # been shown it, so the decoder's last partial character belongs
            # with it rather than nowhere.
            if relay is not None:
                relay.close()
        duration = self._clock() - started

        raw = result.stdout or b""
        if result.returncode != 0 and \
                self.status(handle).state is not State.RUNNING:
            raise SandboxNotRunning(handle.name)

        return ExecResult(
            exit_code=result.returncode,
            output=scrub_output(raw[:MAX_OUTPUT_BYTES]),
            truncated=len(raw) > MAX_OUTPUT_BYTES,
            duration=duration)

    # -- helpers -----------------------------------------------------

    def _exists(self, name: str) -> bool:
        result = self._docker(
            ["ps", "--all", "--filter", f"name=^{name}$",
             "--format", "{{.Names}}"])
        return bool((result.stdout or "").strip())

    def _ensure_network(self, name: str) -> None:
        result = self._docker(
            ["network", "ls", "--filter", f"name=^{name}$",
             "--format", "{{.Name}}"])
        if (result.stdout or "").strip():
            return
        self._checked(network_argv(name), what=f"creating network {name}")


def _require_handle(handle):
    if not isinstance(handle, Handle):
        raise SandboxConfigError(
            f"expected a Handle, got {type(handle).__name__}")
    return handle
